package org.apache.commons.compress.utils;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.Closeable;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.*;

public class IOUtils_skip_TriageGen0Test {

    @Test
    public void testSkip_SuccessWithSkipMethod() throws IOException {
        byte[] data = new byte[100];
        for (int i = 0; i < 100; i++) {
            data[i] = (byte) i;
        }
        InputStream input = new ByteArrayInputStream(data);

        long skipped = IOUtils.skip(input, 50);

        assertEquals(50L, skipped);
        assertEquals(50, input.available());
        assertEquals((byte) 50, input.read());
    }

    @Test
    public void testSkip_ZeroToSkip() throws IOException {
        byte[] data = new byte[]{1, 2, 3};
        InputStream input = new ByteArrayInputStream(data);

        long skipped = IOUtils.skip(input, 0);

        assertEquals(0L, skipped);
        assertEquals(3, input.available());
    }

    @Test
    public void testSkip_PartialSkipThenRead() throws IOException {
        // Simulate a stream where skip() returns 0 or less than requested, 
        // forcing the logic into the readFully block.
        InputStream mockInput = mock(InputStream.class);

        // First call to skip returns 5, but we want to skip 10.
        // Second call to skip returns 0 to trigger the "if (skipped == 0) break"
        when(mockInput.skip(10L)).thenReturn(5L);
        when(mockInput.skip(5L)).thenReturn(0L);

        // The remaining 5 must be read via readFully (which calls input.read)
        // We simulate readFully by mocking the read behavior
        // Note: IOUtils.readFully uses input.read(byte[], int, int)
        when(mockInput.read(any(byte[].class), anyInt(), anyInt())).thenAnswer(invocation -> {
            byte[] b = invocation.getArgument(0);
            int offset = invocation.getArgument(1);
            int len = invocation.getArgument(2);
            for (int i = 0; i < len; i++) {
                b[offset + i] = 1;
            }
            return len;
        });

        long skipped = IOUtils.skip(mockInput, 10L);

        assertEquals(10L, skipped);
        verify(mockInput, atLeastOnce()).skip(anyLong());
    }

    @Test
    public void testSkip_SkipMoreThanAvailable() throws IOException {
        byte[] data = new byte[]{1, 2, 3};
        InputStream input = new ByteArrayInputStream(data);

        // Try to skip 10 bytes when only 3 exist
        long skipped = IOUtils.skip(input, 10L);

        assertEquals(3L, skipped);
        assertEquals(0, input.available());
    }

    @Test
    public void testSkip_ReadFullyReturnsLessThanRequested() throws IOException {
        InputStream mockInput = mock(InputStream.class);

        // skip() returns 0 immediately
        when(mockInput.skip(anyLong())).thenReturn(0L);

        // readFully attempts to read the remaining numToSkip
        // We simulate it returning -1 (EOF) or 0
        when(mockInput.read(any(byte[].class), anyInt(), anyInt())).thenReturn(-1);

        long skipped = IOUtils.skip(mockInput, 10L);

        // Since read < 1, it breaks, returning available - numToSkip (10 - 10 = 0)
        assertEquals(0L, skipped);
    }

    @Test
    public void testSkip_LargeSkipWithMultipleReadCycles() throws IOException {
        // Testing the while(numToSkip > 0) loop inside the readFully block
        // We need a stream that doesn't support skip() well
        InputStream mockInput = mock(InputStream.class);

        when(mockInput.skip(anyLong())).thenReturn(0L);

        // First read returns 2, second read returns 2, third returns -1
        when(mockInput.read(any(byte[].class), anyInt(), anyInt()))
            .thenReturn(2)
            .thenReturn(2)
            .thenReturn(-1);

        long skipped = IOUtils.skip(mockInput, 10L);

        // Total skipped should be 4
        assertEquals(4L, skipped);
    }
}
